CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, password TEXT, platform INTEGER NOT NULL DEFAULT 0 CHECK(platform IN (0,1)), created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_platform_operator ON users(platform) WHERE platform=1;
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE recovery_codes (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id));
CREATE INDEX recovery_user ON recovery_codes(user_id);
CREATE TABLE auth_claims(hash TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE throttle (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX throttle_expiry ON throttle(expires_at);
CREATE TABLE centers (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), timezone TEXT NOT NULL DEFAULT 'Asia/Dhaka', locale TEXT NOT NULL DEFAULT 'en' CHECK(locale IN ('en','bn')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), revision INTEGER NOT NULL DEFAULT 1, late_minutes INTEGER NOT NULL DEFAULT 15 CHECK(late_minutes BETWEEN 1 AND 1440));
CREATE TABLE memberships (center_id TEXT NOT NULL REFERENCES centers(id), user_id TEXT NOT NULL REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(center_id,user_id));
CREATE INDEX memberships_user ON memberships(user_id,active,center_id);
CREATE TABLE roles (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, permissions TEXT NOT NULL CHECK(json_valid(permissions)), version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id));
CREATE INDEX roles_center ON roles(center_id,active,id);
CREATE TABLE member_roles (center_id TEXT NOT NULL, user_id TEXT NOT NULL, role_id TEXT NOT NULL, PRIMARY KEY(center_id,user_id,role_id), FOREIGN KEY(center_id,user_id) REFERENCES memberships(center_id,user_id), FOREIGN KEY(center_id,role_id) REFERENCES roles(center_id,id));
CREATE TABLE invitations (hash TEXT PRIMARY KEY, center_id TEXT REFERENCES centers(id), user_id TEXT NOT NULL REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, role_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(role_ids)));
CREATE TRIGGER auth_claim_valid BEFORE INSERT ON auth_claims WHEN NOT EXISTS(SELECT 1 FROM invitations WHERE hash=NEW.hash AND expires_at>NEW.created_at) AND NOT EXISTS(SELECT 1 FROM recovery_codes WHERE hash=NEW.hash) BEGIN SELECT RAISE(ABORT,'INVALID_AUTH_TOKEN'); END;
CREATE TABLE catalog (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), kind TEXT NOT NULL CHECK(kind IN ('class','session','subject','group','series')), name TEXT NOT NULL, class_id TEXT, session_id TEXT, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id), FOREIGN KEY(center_id,class_id) REFERENCES catalog(center_id,id), FOREIGN KEY(center_id,session_id) REFERENCES catalog(center_id,id));
CREATE INDEX catalog_list ON catalog(center_id,kind,active,name,id);
CREATE TABLE students (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, identifier TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id));
CREATE INDEX students_list ON students(center_id,active,name,id);
CREATE INDEX students_identifier ON students(center_id,identifier);
CREATE TRIGGER student_conflict BEFORE UPDATE ON students WHEN NEW.version!=OLD.version+1 BEGIN SELECT RAISE(ABORT,'RESULT_CONFLICT'); END;
CREATE TABLE contacts (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), phone TEXT NOT NULL, suppressed INTEGER NOT NULL DEFAULT 0, UNIQUE(center_id,id), UNIQUE(center_id,phone));
CREATE TABLE student_contacts (center_id TEXT NOT NULL, student_id TEXT NOT NULL, contact_id TEXT NOT NULL, label TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('student','guardian')), permitted INTEGER NOT NULL CHECK(permitted IN (0,1)), PRIMARY KEY(center_id,student_id,contact_id,audience), FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id), FOREIGN KEY(center_id,contact_id) REFERENCES contacts(center_id,id));
CREATE TABLE group_members (center_id TEXT NOT NULL, group_id TEXT NOT NULL, student_id TEXT NOT NULL, joined_at INTEGER NOT NULL, left_at INTEGER, PRIMARY KEY(center_id,group_id,student_id), FOREIGN KEY(center_id,group_id) REFERENCES catalog(center_id,id), FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id));
CREATE INDEX group_members_student ON group_members(center_id,student_id,left_at,group_id);
CREATE TABLE exams (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, exam_date TEXT NOT NULL, series_id TEXT, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id), FOREIGN KEY(center_id,series_id) REFERENCES catalog(center_id,id));
CREATE INDEX exams_list ON exams(center_id,active,exam_date,id);
CREATE TABLE papers (id TEXT PRIMARY KEY, center_id TEXT NOT NULL, exam_id TEXT NOT NULL, subject_id TEXT NOT NULL, maximum INTEGER NOT NULL CHECK(maximum>0 AND maximum<=999999999), pass_mark INTEGER CHECK(pass_mark>=0 AND pass_mark<=maximum), position INTEGER NOT NULL DEFAULT 0, UNIQUE(center_id,id), UNIQUE(center_id,exam_id,subject_id), FOREIGN KEY(center_id,exam_id) REFERENCES exams(center_id,id), FOREIGN KEY(center_id,subject_id) REFERENCES catalog(center_id,id));
CREATE INDEX papers_exam ON papers(center_id,exam_id,position,id);
CREATE TABLE participants (center_id TEXT NOT NULL, exam_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(center_id,exam_id,student_id), FOREIGN KEY(center_id,exam_id) REFERENCES exams(center_id,id), FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id));
CREATE TABLE results (center_id TEXT NOT NULL, paper_id TEXT NOT NULL, student_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('scored','absent','pending','exempt')), score INTEGER, version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(center_id,paper_id,student_id), FOREIGN KEY(center_id,paper_id) REFERENCES papers(center_id,id), FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id), CHECK((status='scored' AND score IS NOT NULL AND score>=0) OR (status!='scored' AND score IS NULL)));
CREATE TRIGGER result_max_insert BEFORE INSERT ON results WHEN NEW.score>(SELECT maximum FROM papers WHERE center_id=NEW.center_id AND id=NEW.paper_id) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TRIGGER result_max_update BEFORE UPDATE ON results WHEN NEW.score>(SELECT maximum FROM papers WHERE center_id=NEW.center_id AND id=NEW.paper_id) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TRIGGER result_participant BEFORE INSERT ON results WHEN NOT EXISTS(SELECT 1 FROM participants p JOIN papers x ON x.center_id=p.center_id AND x.exam_id=p.exam_id WHERE x.id=NEW.paper_id AND p.center_id=NEW.center_id AND p.student_id=NEW.student_id) BEGIN SELECT RAISE(ABORT,'INVALID_PARTICIPANT'); END;
CREATE TRIGGER result_conflict BEFORE UPDATE ON results WHEN NEW.version!=OLD.version+1 BEGIN SELECT RAISE(ABORT,'RESULT_CONFLICT'); END;
CREATE TRIGGER paper_max_update BEFORE UPDATE OF maximum ON papers WHEN EXISTS(SELECT 1 FROM results WHERE center_id=OLD.center_id AND paper_id=OLD.id AND score>NEW.maximum) BEGIN SELECT RAISE(ABORT,'MARK_EXCEEDS_MAX'); END;
CREATE TABLE templates (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('subject','summary','announcement')), body TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(center_id,id));
CREATE INDEX templates_list ON templates(center_id,active,id);
CREATE TABLE provider_configs (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), api_key TEXT NOT NULL, sender_ids TEXT NOT NULL CHECK(json_valid(sender_ids)), batch_size INTEGER NOT NULL DEFAULT 1 CHECK(batch_size BETWEEN 1 AND 100), interval_seconds INTEGER NOT NULL DEFAULT 2 CHECK(interval_seconds BETWEEN 1 AND 300), active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE(center_id,id));
CREATE UNIQUE INDEX provider_active ON provider_configs(center_id) WHERE active=1;
CREATE TABLE balances (center_id TEXT NOT NULL, config_id TEXT NOT NULL, balance TEXT, estimate_sms INTEGER, checked_at INTEGER, refreshing_until INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(center_id,config_id), FOREIGN KEY(center_id,config_id) REFERENCES provider_configs(center_id,id));
CREATE TABLE campaigns (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), name TEXT NOT NULL, authorizer TEXT NOT NULL REFERENCES users(id), selection TEXT NOT NULL CHECK(json_valid(selection)), state TEXT NOT NULL DEFAULT 'preparing', revision INTEGER NOT NULL, config_id TEXT, cursor TEXT NOT NULL DEFAULT '', scheduled_at INTEGER, scheduled_timezone TEXT NOT NULL DEFAULT 'Asia/Dhaka', created_at INTEGER NOT NULL, total INTEGER NOT NULL DEFAULT 0, excluded INTEGER NOT NULL DEFAULT 0, submitted INTEGER NOT NULL DEFAULT 0, delivered INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, unknown INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0, reason TEXT, idempotency_key TEXT NOT NULL, UNIQUE(center_id,id), UNIQUE(center_id,idempotency_key), FOREIGN KEY(center_id,config_id) REFERENCES provider_configs(center_id,id));
CREATE TABLE campaign_transitions (campaign_id TEXT PRIMARY KEY REFERENCES campaigns(id), expected_revision INTEGER NOT NULL);
CREATE TRIGGER campaign_transition_valid BEFORE INSERT ON campaign_transitions WHEN NOT EXISTS(SELECT 1 FROM campaigns c JOIN centers x ON x.id=c.center_id WHERE c.id=NEW.campaign_id AND c.state='ready_for_review' AND c.total>0 AND c.revision=x.revision AND c.revision=NEW.expected_revision) BEGIN SELECT RAISE(ABORT,'PREVIEW_CHANGED'); END;
CREATE INDEX campaigns_list ON campaigns(center_id,created_at DESC,id);
CREATE INDEX campaigns_due ON campaigns(state,scheduled_at,id);
CREATE TABLE messages (id TEXT PRIMARY KEY, center_id TEXT NOT NULL, campaign_id TEXT NOT NULL, student_id TEXT NOT NULL, student_name TEXT NOT NULL, contact_id TEXT NOT NULL, phone TEXT NOT NULL, body TEXT NOT NULL, segments INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', provider_id TEXT, reason TEXT, claim TEXT, submitted_at INTEGER, next_check_at INTEGER, check_count INTEGER NOT NULL DEFAULT 0, logical_key TEXT NOT NULL, UNIQUE(center_id,id), UNIQUE(center_id,campaign_id,logical_key), FOREIGN KEY(center_id,campaign_id) REFERENCES campaigns(center_id,id), FOREIGN KEY(center_id,student_id) REFERENCES students(center_id,id), FOREIGN KEY(center_id,contact_id) REFERENCES contacts(center_id,id));
CREATE INDEX messages_campaign ON messages(center_id,campaign_id,state,id);
CREATE INDEX messages_checks ON messages(state,next_check_at,id);
CREATE TRIGGER message_total AFTER INSERT ON messages BEGIN UPDATE campaigns SET total=total+1 WHERE center_id=NEW.center_id AND id=NEW.campaign_id; END;
CREATE TABLE jobs (id TEXT PRIMARY KEY, center_id TEXT NOT NULL, campaign_id TEXT NOT NULL, due_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, published_at INTEGER, exhausted INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(center_id,campaign_id) REFERENCES campaigns(center_id,id));
CREATE INDEX jobs_due ON jobs(exhausted,due_at,published_at,id);
CREATE TABLE attempts (id TEXT PRIMARY KEY, center_id TEXT NOT NULL REFERENCES centers(id), campaign_id TEXT NOT NULL, message_id TEXT NOT NULL, created_at INTEGER NOT NULL, outcome TEXT NOT NULL);
CREATE INDEX attempts_message ON attempts(center_id,message_id,created_at);
CREATE TABLE audit (id TEXT PRIMARY KEY, center_id TEXT REFERENCES centers(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX audit_center ON audit(center_id,created_at DESC,id);

CREATE TRIGGER student_revision_insert AFTER INSERT ON students BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER student_revision_update AFTER UPDATE ON students BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER contact_revision_update AFTER UPDATE ON contacts BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER student_contact_revision_insert AFTER INSERT ON student_contacts BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER student_contact_revision_delete AFTER DELETE ON student_contacts BEGIN UPDATE centers SET revision=revision+1 WHERE id=OLD.center_id; END;
CREATE TRIGGER group_revision_insert AFTER INSERT ON group_members BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER group_revision_update AFTER UPDATE ON group_members BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER result_revision_insert AFTER INSERT ON results BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER result_revision_update AFTER UPDATE ON results BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER paper_revision_insert AFTER INSERT ON papers BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER paper_revision_update AFTER UPDATE ON papers BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER exam_revision_update AFTER UPDATE ON exams BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER catalog_revision_update AFTER UPDATE ON catalog BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER template_revision_update AFTER UPDATE ON templates BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER participant_revision_insert AFTER INSERT ON participants BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
CREATE TRIGGER provider_revision_insert AFTER INSERT ON provider_configs BEGIN UPDATE centers SET revision=revision+1 WHERE id=NEW.center_id; END;
